 foreach(var theme in new[]{"Sky","Astro"}){send(new{type="layout",width=1000,height=700,cards=new[]{new{name="Dock",x=70,y=540,w=860,h=100,r=34,fixedShape=false},new{name="Workspace",x=70,y=60,w=860,h=400,r=32,fixedShape=true},new{name="Hover",x=150,y=150,w=80,h=80,r=16,fixedShape=true}},theme=theme,paused=false});display.Invoke(label,new object[]{"文件资源管理器",dock,.5,false});await Task.Delay(400);Check(await Eval("document.querySelector('#dock-name').textContent==='文件资源管理器'&&getComputedStyle(document.querySelector('#dock-name')).display==='flex'")=="true",theme+" caption appears in the shared renderer");var plate=(Form)type.GetField("plate",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(label);Check(IsWindowVisible(plate.Handle)&&plate.Region.IsVisible(plate.Width/2,plate.Height/2)&&!plate.Region.IsVisible(0,0),theme+" native clip has round capsule ends");using(var stream=File.Create(Path.Combine(output,theme+".png")))await view.CoreWebView2.CapturePreviewAsync(CoreWebView2CapturePreviewImageFormat.Png,stream);
