 using(var pixels=new Bitmap(form.Width,form.Height)){using(var g=Graphics.FromImage(pixels))g.CopyFromScreen(form.Location,Point.Empty,pixels.Size);pixels.Save(Path.Combine(output,theme+"-composited.png"));var red=pixels.GetPixel(500,542);Check(red.R==255&&red.G==0&&red.B==0,theme+" label thumbnail cannot copy a Dock stripe over the foreground icon");Check(pixels.GetPixel(200,200).B<240,"native glass is visible above the white fixture window");Check(pixels.GetPixel(70,60).R>245&&pixels.GetPixel(70,60).G>245,theme+" native window reveals the white window behind its corner");}}
 foreach(var theme in new[]{"Sky","Astro"}){
