 using(var left=new Bitmap(Path.Combine(output,theme+"-hover-left.png")))using(var right=new Bitmap(Path.Combine(output,theme+"-hover-right.png"))){int shape=0,light=0;for(int x=70;x<930;x++)for(int y=530;y<650;y++){var a=left.GetPixel(x,y);var b=right.GetPixel(x,y);if(Math.Abs(a.A-b.A)>32)shape++;if(a.A==255&&b.A==255&&Math.Abs(a.R-b.R)+Math.Abs(a.G-b.G)+Math.Abs(a.B-b.B)>60)light++;}Check(shape>200,theme+" hover visibly deforms the actual glass silhouette");Check(light>200,theme+" cursor-following colored light remains visible in rendered pixels");}
 }
 type.GetMethod("Hide").Invoke(label,null);await Wait("getComputedStyle(document.querySelector('#dock-name')).display==='none'");Check(await Eval("getComputedStyle(document.querySelector('#dock-name')).display==='none'")=="true","fade out removes the caption from the shared scene");display.Invoke(label,new object[]{"减少动画",dock,.5,true});type.GetMethod("Hide").Invoke(label,null);await Wait("getComputedStyle(document.querySelector('#dock-name')).display==='none'");Check(!IsWindowVisible(((Form)type.GetField("plate",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(label)).Handle),"reduced motion hides the native plate immediately");Check(await Eval("!window.visualError")=="true","no browser error");File.AppendAllText(Path.Combine(output,"checks.txt"),"Completed "+checks+" native shared-glass checks.\n");
 }catch(Exception ex){File.AppendAllText(Path.Combine(output,"checks.txt"),ex.ToString());Environment.ExitCode=1;}finally{if(label!=null)label.Dispose();view.Dispose();form.Close();if(icon!=null)icon.Dispose();if(backdrop!=null)backdrop.Close();}};Application.Run(form);}
